SELECT TEMP.FINPROD_ID finprodId, ROUND(TEMP.amountSum * fcp.PRIN_AMT,2) AS amount FROM ( SELECT psp.FINPROD_ID, SUM(AMOUNT) amountSum FROM PTL_SEC_POSITION psp LEFT JOIN FIN_PRODUCT_TYPE fpt ON psp.FINPROD_ID = fpt.FINPROD_ID WHERE to_char(psp.CDATE,'yyyy-MM-dd') = #{benchDate} AND psp.HODING_TYPE = #{POSITION_TYPE}
AND fpt.TYPE_9 IN
#{type}
AND fpt.TYPE_10 IN
#{type}
AND fpt.TYPE_11 IN
#{type}
AND fpt.TYPE_12 IN
#{type}
GROUP BY psp.FINPROD_ID )TEMP LEFT JOIN FIN_CASH_PLAN fcp ON fcp.FINPROD_ID = TEMP.FINPROD_ID LEFT JOIN FIN_PRODUCT fp ON fp.FINPROD_ID = TEMP.FINPROD_ID WHERE to_char(fcp.PAY_DATE,'yyyy-MM-dd') >= #{vdate} AND to_char(fcp.PAY_DATE,'yyyy-MM-dd') <= #{edate} AND TEMP.amountSum <> 0 AND fcp.CASH_TYPE IN ('${middle}','${end}') AND fp.FINPROD_TYPE2 = '${prodType}' AND (fp.IS_RIGHT = #{NO} or fp.IS_RIGHT is null)
UNION
SELECT TEMP.FINPROD_ID finprodId, ROUND(TEMP.amountSum * fcp.PRIN_AMT,2) AS amount FROM ( SELECT psp.FINPROD_ID, SUM(AMOUNT) amountSum FROM PTL_SEC_POSITION psp LEFT JOIN FIN_PRODUCT_TYPE fpt ON psp.FINPROD_ID = fpt.FINPROD_ID WHERE to_char(psp.CDATE,'yyyy-MM-dd') = #{benchDate} AND psp.HODING_TYPE = #{POSITION_TYPE}
AND fpt.TYPE_9 IN
#{type}
AND fpt.TYPE_10 IN
#{type}
AND fpt.TYPE_11 IN
#{type}
AND fpt.TYPE_12 IN
#{type}
GROUP BY psp.FINPROD_ID )TEMP LEFT JOIN FIN_CASH_PLAN fcp ON fcp.FINPROD_ID = TEMP.FINPROD_ID LEFT JOIN FIN_PRODUCT fp ON fp.FINPROD_ID = TEMP.FINPROD_ID WHERE to_char(fcp.PAY_DATE,'yyyy-MM-dd') >= #{vdate} AND to_char(fcp.PAY_DATE,'yyyy-MM-dd') <= #{edate} AND TEMP.amountSum <> 0 AND fcp.CASH_TYPE IN ('${middle}','${end}') AND fp.FINPROD_TYPE2 = #{prodType} AND fp.IS_RIGHT = #{YES} AND ( (select min(fep.EXERCISE_DATE) from FIN_EXERCISE_PLAN fep where to_char(fep.EXERCISE_DATE,'yyyy-MM-dd') >= #{vdate} and fp.FINPROD_ID = fep.FINPROD_ID) is null or fcp.PAY_DATE < ( select min(fep.EXERCISE_DATE) from FIN_EXERCISE_PLAN fep where to_char(fep.EXERCISE_DATE,'yyyy-MM-dd') >= #{vdate} and fep.EXERCISE_TYPE IN ('${SH}','${HS}') and fp.FINPROD_ID = fep.FINPROD_ID) ) UNION
SELECT TEMP.FINPROD_ID finprodId, ROUND(TEMP.amountSum * (100 - FCASH.prinSum),2) AS amount FROM ( SELECT psp.FINPROD_ID, SUM(AMOUNT) amountSum FROM PTL_SEC_POSITION psp LEFT JOIN FIN_PRODUCT_TYPE fpt ON psp.FINPROD_ID = fpt.FINPROD_ID WHERE to_char(psp.CDATE,'yyyy-MM-dd') = #{benchDate} AND psp.HODING_TYPE = #{POSITION_TYPE}
AND fpt.TYPE_9 IN
#{type}
AND fpt.TYPE_10 IN
#{type}
AND fpt.TYPE_11 IN
#{type}
AND fpt.TYPE_12 IN
#{type}
GROUP BY psp.FINPROD_ID )TEMP LEFT JOIN FIN_PRODUCT fp ON fp.FINPROD_ID = TEMP.FINPROD_ID LEFT JOIN FIN_EXERCISE_PLAN fep ON fep.FINPROD_ID = TEMP.FINPROD_ID LEFT JOIN ( select fcp.FINPROD_ID, sum(PRIN_AMT) prinSum from FIN_CASH_PLAN fcp where to_char(fcp.PAY_DATE,'yyyy-MM-dd') < #{vdate} and fcp.CASH_TYPE IN ('${middle}','${end}') and fcp.FINPROD_TYPE2 = #{prodType} group by fcp.FINPROD_ID )FCASH ON FCASH.FINPROD_ID = fp.FINPROD_ID WHERE to_char(fep.EXERCISE_DATE,'yyyy-MM-dd') >= #{vdate} AND to_char(fep.EXERCISE_DATE,'yyyy-MM-dd') <= #{edate} AND TEMP.amountSum <> 0 AND fp.FINPROD_TYPE2 = #{prodType} AND fp.IS_RIGHT = #{YES} AND fep.ACT_EXERCISE_DATE IS NOT NULL AND fep.EXERCISE_DATE = ( select min(fep.EXERCISE_DATE) from FIN_EXERCISE_PLAN fep where to_char(fep.EXERCISE_DATE,'yyyy-MM-dd') >= #{vdate} and fep.EXERCISE_TYPE IN ('${SH}','${HS}') and fp.FINPROD_ID = fep.FINPROD_ID)

SELECT tco.TACTIC_CONFIG_CODE tacticConfigCode, tco.VDATE, tco.EDATE, tco.OPINION_RINV opinionRinv, tcod.THEO_CONFIG_RATE theoConfigRate, tcod.SAMLE_AVER_RATE samleAverRate, tcod.VIX, tcod.COR_RATE corRate, tcod.COR_SCENE corScene, tcod.COR_RATIO corRatio, tcod.COR_VIEW corView, tcod.ASSET_TYPE assetType FROM TACTIC_CONFIG_OPT tco INNER JOIN TACTIC_CONFIG_OPT_DETAIL tcod ON tco.TACTIC_CONFIG_CODE = tcod.TACTIC_CONFIG_CODE
AND to_char(tco.VDATE,'yyyy-MM-dd') = #{vdate}
AND to_char(tco.EDATE,'yyyy-MM-dd') = #{edate}

SELECT

FROM PRD_PLAN_INFO
WHERE VDATE = #{vdate,jdbcType=DATE}
AND EDATE = #{edate,jdbcType=DATE}

select

from ASSET_PLAN_INFO
WHERE VDATE = #{vdate,jdbcType=DATE}
AND EDATE = #{edate,jdbcType=DATE}

select to_char(PAY_DATE,'YYYYMM') as assetMonth,sum(curEndAmt) curEndAmt from ( select ZCCC.FINPROD_ID FINPROD_ID, FIN_CASH_PLAN.PAY_DATE PAY_DATE, (case when FIN_PRODUCT.FINPROD_TYPE2 = 'F01' then round(ZCCC.AMOUNT*FIN_CASH_PLAN.PRIN_AMT,2) when NVL(FIN_PRODUCT.ISSUE_AMT,0) - NVL(YHBFX.PAID_AMT,0) = 0 then 0 else round(ZCCC.AMOUNT*FIN_CASH_PLAN.PRIN_AMT/(NVL(FIN_PRODUCT.ISSUE_AMT,0) - NVL(YHBFX.PAID_AMT,0)),2) end) curEndAmt from ( SELECT SUM(A.AMOUNT) AMOUNT, A.FINPROD_ID FINPROD_ID FROM PTL_SEC_POSITION A LEFT JOIN FIN_PRODUCT_TYPE B ON A.FINPROD_ID = B.FINPROD_ID WHERE A.HODING_TYPE = #{holdingType,jdbcType=VARCHAR}
and A.CDATE = to_date(#{cdate}, 'yyyy-MM-dd')
and B.TYPE_9 IN
#{item}
and B.TYPE_10 IN
#{item}
and B.TYPE_11 IN
#{item}
and B.TYPE_12 IN
#{item}
group by A.FINPROD_ID ) ZCCC JOIN FIN_CASH_PLAN ON ZCCC.FINPROD_ID = FIN_CASH_PLAN.FINPROD_ID JOIN FIN_PRODUCT ON ZCCC.FINPROD_ID = FIN_PRODUCT.FINPROD_ID LEFT JOIN ( select sum(PRIN_AMT) PAID_AMT,FIN_CASH_PLAN.FINPROD_ID AS FINPROD_ID from FIN_CASH_PLAN where FIN_CASH_PLAN.MDATE <=to_date(#{benchDate}, 'yyyy-MM-dd') and FIN_CASH_PLAN.CASH_TYPE in ('02','03') group by FIN_CASH_PLAN.FINPROD_ID ) YHBFX on ZCCC.FINPROD_ID = YHBFX.FINPROD_ID where FIN_CASH_PLAN.PAY_DATE >=to_date(#{benchDate}, 'yyyy-MM-dd') and FIN_CASH_PLAN.PAY_DATE <=to_date(#{benchDateEnd}, 'yyyy-MM-dd') and ZCCC.AMOUNT !=0 and FIN_CASH_PLAN.CASH_TYPE in ('02','03') ) TEMP group by to_char(PAY_DATE,'YYYYMM')
